import java.util.HashMap;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;

public class CycleLength {
    public static int n = 8;
    public static int k = 2;

    public static String sequence = ""
    		+ "";

    public static String[] CCR1 = {"0000111100101101", "00000111110010011011000101110101", "0000001111110001101110011001010110101001000100111011000010111101", "00000001111111000110011100110001010111010101000100011101110000110111100101001101011001001011011010010000100111101100000101111101", "0000000011111111000011101111000110101110010110011010011001010101101010100101000110001110011100010110111010010001010011101011000100101110110100010000110011110011000010101111010100001000111101110000011011111001001001101101100100000100111110110000001011111101", "", ""};
    public static String[] CCR2 = {"0000111100101101", "00000111110010011011000101110101", "0000001111110001001110110011000010111101001010110101000110111001", "00000001111111000100011101110000100111101100101001101011000110011100110000010111110100100101101101000101011101010100001101111001", "0000000011111111000010001111011100011000111001110000010011111011001001001101101100010100111010110000110011110011001011001101001100000010111111010001001011101101000010101111010100101010110101010001101011100101000001101111100100010110111010010000111011110001", "", ""};
    public static String[] CCR3 = {"0000101101001111", "00000100110110010101110100011111", "0000001001110110001010110101001011110100001100110111001000111111", "00000001000111011100010010110110100100111101100001010011010110010101011101010001011111010000011001110011000110111100100001111111", "0000000010001111011100001001001101101100100101110110100010011111011000001010011101011000101010110101010010101111010100001011001101001100101101110100100010111111010000001100011100111000110011110011000011010111001010001101111100100000111011110001000011111111", "", ""};
    public static String[] CCR4 = {"0000111101001011", "00000111110101000101110010011011", "0000001111110101001010110100001011110011001000110111000100111011", "00000001111111010101000101011101000001011111001100011001110010100110101100100001101111000100011101110000100111101101001001011011", "0000000011111111010101001010101101010000101011110100100010110111010000001011111100111000110001110011010011001011001100001100111100101000110101110010000011011111000101001110101100010000111011110000100011110111000001001111101101000100101110110010010011011011", "", ""};
    
    public static String[] PrefSame = {"1111000011010010", "11111000001110110011010001001010", "1111110000001111011100111010000100011000101100100110110101001010", "11111110000000111110111100111101000001000011000010111000111001000110111011000100111010110011001011011010011010100010100100101010", "1111111100000000111111011111001111101000000100000110000010111100011110010000111000011011110110000100111101011100010001110111001100011001110010111011011101001110101000010100011010001001000101100010101100110110010011001010011010110110100100101101010100101010", "", ""};
    public static String[] LexComp = {"1111000011010010", "11111000001110110011010001001010", "1111110000001111011100111010000100011000101100100110110101001010", "11111110000000111110111100111101000001000011000010111000111001000110111011000100111010110011001011011010100010100110100100101010", "1111111100000000111111011111001111101000000100000110000010111100011110010000111000011011110110000100111101011100010001110111001100011001110010111011011101001110101000010100011010001001000101100010101100110110010100110010011010110110100100101101010100101010", "", ""};
    public static String[] RunLength = {"1111010010110000", "11111010100110010001011011100000", "1111110101001001100011011001110010101101000100001011101111000000", "11111110101010010010110010001100001101110011110010100010101101100011100010011101101001100110101110100001000001011110111110000000", "1111111101010100101001101100110001100111001101000110101100100110010111001000011000001101111001111100101010110100111010010010001001011000100011100001110111000111100010110110111011000010011110110101000101000010101110101111010000010000001011111011111100000000", "", ""};
    public static String[] PrefOpp = {"0101001101111000", "01010110100100011001110111110000", "0101010010110101110100010011011001000011000111001111011111100000", "01010101101010010100010110010111010111101001101000010010011101101100010001101110010000011001100001110001111001111101111111000000", "0101010100101011010101110101000101001101011001010000101101101001001011000101110010111101011111010011101000110100000100100010011001001111011011101100110110000100011101110001000011011110010000001100111001100011000001110000111100011111001111110111111110000000", "", ""};
    public static String[] LC2 = {"0101001111011000", "01010110100100011001111101110000", "0101010010111010110100010011011001000011000111111011110011100000", "01010101101010010100010110010111101011101001101000010010011101101100010001101110010000011001100001110001111111011111001111000000", "0101010100101011101010110101000101001101011001010000101101101001001011000101110010111110101111010011101000110100000100100010011001001111011011101100110110000100011101110001000011011110010000001100111001100011000001110000111111110111111001111100011110000000", "", ""};
    public static String[] RunLength2 = {"0101111001000011", "01010010111110011000100000111011", "0101011111100011000010000001110011011001001111011101001010001011", "01010100101011111110001101101110010010001110000110000010000000111100110011101100101100010011010011111011110100010100001011101011", "0101010111111110000110111011011010010010110111100100010010000111000001100000010000000011110001110111001011100010001101000111110011100110010011000110011011001111011000101100001001110100110101100101001111110111110100001010000010111101011101010010101000101011", "", ""};
    
    public static HashMap<String, Integer> cycleLengths = new HashMap<>();

    public static void main(String[] args) {
        String[] names = {"CCR1", "CCR2", "CCR3", "CCR4", "PrefSame", "LexComp", "RunLength", "PrefOpp", "LC2", "RunLength2"};
        String[][] algorithms = {CCR1, CCR2, CCR3, CCR4, PrefSame, LexComp, RunLength, PrefOpp, LC2, RunLength2};

        // allResults: algorithm name -> list of cycle-length maps, index 0 = n=4 ... index 4 = n=8
        HashMap<String, List<HashMap<String, Integer>>> allResults = new HashMap<>();

        for (int a = 0; a < algorithms.length; a++) {
            List<HashMap<String, Integer>> resultsByN = new ArrayList<>();
            for (int i = 0; i < algorithms[a].length; i++) {
                n = i + 4;
                sequence = algorithms[a][i];
                cycleLengths = new HashMap<>();
                function();
                fixCycleLengths();
                resultsByN.add(new HashMap<>(cycleLengths));
            }
            allResults.put(names[a], resultsByN);
        }

        StringBuilder json = new StringBuilder();
        json.append("{\n");
        for (int a = 0; a < names.length; a++) {
            json.append("  \"").append(names[a]).append("\": {\n");
            List<HashMap<String, Integer>> resultsByN = allResults.get(names[a]);
            for (int i = 0; i < resultsByN.size(); i++) {
                int nVal = i + 4;
                cycleLengths = resultsByN.get(i);
                n = nVal;
                LinkedHashMap<String, Integer> byKey = sortByKey();
                LinkedHashMap<String, Integer> byCycle = sortByCycleLength();

                json.append("    \"n=").append(nVal).append("\": {\n");

                json.append("      \"sortedByKey\": {\n");
                appendEntries(json, byKey);
                json.append("      },\n");

                json.append("      \"sortedByCycleLength\": {\n");
                appendEntries(json, byCycle);
                json.append("      }\n");

                json.append("    }");
                if (i < resultsByN.size() - 1) json.append(",");
                json.append("\n");
            }
            json.append("  }");
            if (a < names.length - 1) json.append(",");
            json.append("\n");
        }
        json.append("}");

        try (FileWriter fw = new FileWriter("cycle_lengths.json")) {
            fw.write(json.toString());
            System.out.println("Results written to cycle_lengths.json");
        } catch (IOException e) {
            e.printStackTrace();
        }
    }

    public static void appendEntries(StringBuilder sb, LinkedHashMap<String, Integer> map) {
        List<Map.Entry<String, Integer>> entries = new ArrayList<>(map.entrySet());
        for (int i = 0; i < entries.size(); i++) {
            sb.append("        \"").append(entries.get(i).getKey()).append("\": ").append(entries.get(i).getValue());
            if (i < entries.size() - 1) sb.append(",");
            sb.append("\n");
        }
    }

    public static void fixCycleLengths() {
        int maxDiff = (int) Math.pow(k, n - 1);
        int seqLength = (int) Math.pow(k, n);
        for (Map.Entry<String, Integer> entry : cycleLengths.entrySet()) {
            if (entry.getValue() > maxDiff) {
                cycleLengths.put(entry.getKey(), seqLength - entry.getValue());
            }
        }
    }

    public static LinkedHashMap<String, Integer> sortByKey() {
        List<String> keys = new ArrayList<>(cycleLengths.keySet());
        Collections.sort(keys);
        LinkedHashMap<String, Integer> sorted = new LinkedHashMap<>();
        for (String key : keys) {
            sorted.put(key, cycleLengths.get(key));
        }
        return sorted;
    }

    public static LinkedHashMap<String, Integer> sortByCycleLength() {
        List<Map.Entry<String, Integer>> entries = new ArrayList<>(cycleLengths.entrySet());
        entries.sort((a, b) -> b.getValue() - a.getValue());
        LinkedHashMap<String, Integer> sorted = new LinkedHashMap<>();
        for (Map.Entry<String, Integer> entry : entries) {
            sorted.put(entry.getKey(), entry.getValue());
        }
        return sorted;
    }

    public static void function(){
    	sequence = sequence + sequence.substring(0, n-1);
    	
        int total = (int) Math.pow(k, n-1);

        int newN = n-1;

        int count = 0;
        int i = 0;

        while (count < total) {
            String current = sequence.substring(i, i+newN);

            if(cycleLengths.containsKey(current)){
            	i++;
                continue;
            }

            for(int j = i+1; j < sequence.length(); j++){
                if(sequence.substring(j, j+newN).equals(current)){
                    cycleLengths.put(current, j-i);
                    break;
                }
            }
            i++;
            count++;

            if(i + newN > sequence.length()){
				break;
			}
        }
    }
}
